package dev.aihub.wellness;
import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.http.MediaType; import org.springframework.test.web.servlet.MockMvc; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest(properties="aihub.data-file=target/test-data/wellness-${random.uuid}.json") @AutoConfigureMockMvc class WellnessApplicationTests { @Autowired MockMvc mvc; @Test void apiWorks() throws Exception { mvc.perform(get("/api/metrics")).andExpect(status().isOk()).andExpect(jsonPath("$.primary").value("plans")); mvc.perform(get("/api/plans")).andExpect(status().isOk()).andExpect(jsonPath("$[0].id").isNumber()); mvc.perform(post("/api/plans").contentType(MediaType.APPLICATION_JSON).content("{\"name\":\"新增演示记录\"}")).andExpect(status().isCreated()); } }